```glsl
float wave(vec2 p, vec2 d, float amp, float k, float speed, float phase, inout vec2 grad) {
  float a = dot(p, d) * k + uTime * speed + phase;
  grad += d * (amp * k * cos(a));
  return amp * sin(a);
}
```

