  rider.add(foot);

  for (let i = 0; i < 3; i++) {
    const toe = new THREE.Mesh(
      new THREE.CapsuleGeometry(0.038, 0.22, 4, 8),
      orangeMat
    );
    toe.rotation.z = -Math.PI / 2;
    toe.rotation.y = (i - 1) * 0.3;
    toe.position.set(0.63, 0.125, side * 0.28 + (i - 1) * 0.075);
    rider.add(toe);
